import{_ as o,l as i,o as e,c as s,v as t,p as d,x as l,d as n,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SPLADE","description":"","frontmatter":{"title":"SPLADE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/splade.md","filePath":"llm/splade.md","lastUpdated":1789023840000}'),A={name:"llm/splade.md"};function h(m,a,_,c,P,S){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="splade" tabindex="-1">SPLADE <a class="header-anchor" href="#splade" aria-label="Permalink to &quot;SPLADE&quot;">​</a></h1><div class="epigraph"><p>让编码器对词表维预测稀疏权重，倒排里就会出现「没写在文里但该被检索到」的扩展词。词法通道由此可学习，而不只靠 BM25 计数。</p><footer>—— Formal 等 SPLADE</footer></div><p><a href="/llm/bm25-sparse">上一课</a>的词袋不能扩同义。查询扩展与同义词表是手工的。Formal 等人的 SPLADE 用预训练语言模型对每个文档（和查询）预测一个词表那么长的稀疏向量，非零维相当于加权后的词，可写入倒排。缺口是把「可学习稀疏」从稠密双塔里拆出来。后课 MTEB 会同时考稀疏、稠密与指令嵌入，不要混成一种模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BM25 只激活文档里出现过的词。用户写「心肌梗死」，文档写「heart attack」，字面零命中。稠密能对上，但标识符又弱。SPLADE 希望：稀疏向量在「心肌梗死」维上有权重，即使原文是英文医学同义。它仍走倒排，延迟与可解释性接近词法，而不是 ANN。</p><p>训练要用对比或蒸馏（向交叉编码器看齐），并对向量加稀疏正则，否则退化为稠密的低效版本：几乎每维都非零，倒排爆炸。</p><p><span class="marginnote">稀疏维是词表下标，人可以读出「模型用哪些词扩展了文档」。这是调试召回的接口，不是保证扩展正确。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对输入做 MLM 式 logits，经激活（如 log-saturation）与池化得到词表维权重，再 L1 / FLOPS 正则压非零数。查询与文档可非对称：查询更短更稀疏。索引：把非零维当 term、权重当冲击值，用学习到的分数代替 BM25 公式。推理延迟取决于平均非零数，必须当指标报。</p>',9)),(e(),d(p,null,{default:l(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20LM%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20logits%22%5D%0A%20%20LM%20--%3E%20SP%5B%22%E7%A8%80%E7%96%8F%E8%AF%8D%E8%A1%A8%E5%90%91%E9%87%8F%22%5D%0A%20%20SP%20--%3E%20INV%5B%22%E5%80%92%E6%8E%92%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E7%A8%80%E7%96%8F%E5%90%91%E9%87%8F%22%5D%20--%3E%20SC%5B%22%E7%82%B9%E7%A7%AF%20%2F%20%E5%80%92%E6%8E%92%E6%B1%82%E5%88%86%22%5D%0A%20%20INV%20--%3E%20SC%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正则迫使模型只点亮少量扩展词。对比损失要求这些词能把正例从难负例里分开，于是点亮的是有判别力的同义与相关词，而不只是高频词。若正则过强，退回近乎字面 BM25；过弱，变成昂贵稠密。与难负例课同样：假相关扩展会伤害精度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>词表是分词器词表，对未登录标识符仍弱——keyword 字段与 BM25 通道仍值得保留，混合检索并不过时。下一课 MTEB：在统一任务套件上比较这些嵌入家族。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPLADE 学习稀疏词表权重，倒排可含扩展词。</li><li>稀疏正则是可用性条件；非零数要当延迟指标。</li><li>不替代 BM25 标识符字段，常作混合一路。</li><li>出处：Formal 等 SPLADE。</li></ul>',6))])}const B=o(A,[["render",h]]);export{f as __pageData,B as default};
